+        entered_recv.recv_timeout(DEADLINE).unwrap();
+        let (audit_send, audit_recv) = mpsc::channel();
+        let audit = scope.spawn(move || {
+            audit_send
+                .send(core_ref.validate_invariants_for_host_model())
